import{z as i,x as s,o as e,c as d,q as l,j as o,D as r,d as n,s as t,S as B,b as E}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"LDPC 与 Turbo 直觉","description":"","frontmatter":{"title":"LDPC 与 Turbo 直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ldpc-turbo.md","filePath":"cs/ldpc-turbo.md","lastUpdated":1791413859000}'),p={name:"cs/ldpc-turbo.md"};function C(u,a,b,m,h,D){const A=s("Mermaid");return e(),d("div",null,[a[2]||(a[2]=l('<h1 id="ldpc-与-turbo-直觉" tabindex="-1">LDPC 与 Turbo 直觉 <a class="header-anchor" href="#ldpc-与-turbo-直觉" aria-label="Permalink to &quot;LDPC 与 Turbo 直觉&quot;">​</a></h1><div class="epigraph"><p>稀疏校验图上的迭代消息传递，以及交织的两个卷积码互相当先验：实践中逼近 Shannon 容量，证明却是密度演化与经验。</p><footer>—— 据 Gallager, 1963；Berrou, Glavieux and Thitimajshima, 1993；Richardson and Urbanke 整理</footer></div><p>上一课<a href="/cs/convolutional-viterbi">卷积与 Viterbi</a> 的状态随记忆指数涨，离容量远。缺口是<strong>近容量码</strong>：LDPC（稀疏 \\(H\\)）与 Turbo（并行级联卷积）。本课直觉：因子图、迭代、门限；不写 5G 标准。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Gallager：校验矩阵稀疏，每个校验含少数变量。译码：在 Tanner 图上传递「这比特是 0/1 的似然」，迭代。环短会骗过迭代，随机大图以高概率好。Turbo：两个系统卷积码，中间交织；解码器交换外信息。二者都不是代数最小距离设计的主路，而是统计物理式的阈值：\\(E_b/N_0\\) 高于门限则错误瀑布下降。</p><p>对照 Hamming/RS：那里 \\(d_{\\min}\\) 精确；这里瀑布 + 错误平层（平层由小重量码字造成）。</p><h3 id="迭代不是最大似然" tabindex="-1">迭代不是最大似然 <a class="header-anchor" href="#迭代不是最大似然" aria-label="Permalink to &quot;迭代不是最大似然&quot;">​</a></h3><p>Viterbi 在网格上 ML。LDPC 的 BP 在有环图上只是近似。容量附近 ML 不可行（码太长），迭代是工程最优。</p><p><span class="marginnote">Gallager 1963 被忽视，1990s 复活。Berrou et al. 1993 Turbo。Richardson–Urbanke 密度演化。MacKay 的现代编码观点。PCP 的「局部校验」不是本课的信道译码。</span></p><p><span class="marginnote">直觉类比：Tanner 图上的迭代像陪审团合议——每个比特节点是一位证人，先按信道观察给出自己的置信度；每个校验节点是一个交叉质证小组，发现「你们几个的说法加起来矛盾」就把修正意见发回去；证人参考意见更新自己的置信度，几轮后达成共识。短环则是几个小组互相小圈子循环背书，合议被带偏。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画一张小 Tanner 图：变量圆、校验方。描述一次迭代。点名：码长 \\(10^4\\) 量级才显近容量，短码仍可用 RS。不要把深度学习译码当定义。</p>',12)),(e(),o(B,null,{default:r(()=>[t(A,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E7%A8%80%E7%96%8F%20H%20%2F%20%E4%BA%A4%E7%BB%87%E5%8D%B7%E7%A7%AF%22%5D%20--%3E%20GRAPH%5B%22%E5%9B%A0%E5%AD%90%E5%9B%BE%22%5D%0A%20%20GRAPH%20--%3E%20BP%5B%22%E8%BF%AD%E4%BB%A3%E6%B6%88%E6%81%AF%E4%BC%A0%E9%80%92%22%5D%0A%20%20BP%20--%3E%20CAP%5B%22%E9%97%A8%E9%99%90%E9%80%BC%E8%BF%91%E5%AE%B9%E9%87%8F%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[n("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"Shannon 随机码不可实现；LDPC/Turbo 是可描述的伪随机码，译码多项式（相对块长）。容量课的存在性至此有构造性近似。外码仍常用 RS 去平层。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"数字实例：典型 LDPC 的校验矩阵每列只有 3 到 6 个 1——一个 10000 比特的码字，每个校验方程只牵扯几个比特。图上邻居数是常数，一次迭代总代价 \\(O(n)\\)；若 H 不稀疏，一个校验连所有比特，迭代一步就是 \\(O(n^2)\\)，长码根本跑不动。")],-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"常见误区：初学者看 LDPC 的性能曲线，以为信噪比再抬高错误率就能无限下降。实际上曲线会在 \\(10^{-6}\\) 到 \\(10^{-9}\\) 附近突然变平（错误平层），元凶是少量小重量码字——所以深空与存储系统常在 LDPC 外面再套一层 RS 代数码把平层压下去。")],-1)),(e(),o(B,null,{default:r(()=>[t(A,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20CH%5B%22%E4%BF%A1%E9%81%93%E8%BE%93%E5%87%BA%3A%20%E6%AF%8F%E6%AF%94%E7%89%B9%E5%B8%A6%E5%99%AA%E4%BC%BC%E7%84%B6%20LLR%22%5D%20--%3E%20VN%5B%22%E5%8F%98%E9%87%8F%E8%8A%82%E7%82%B9%3A%20%E6%B1%87%E6%80%BB%E4%BF%A1%E9%81%93%E5%85%88%E9%AA%8C%E4%B8%8E%E5%90%84%E6%A0%A1%E9%AA%8C%E6%B6%88%E6%81%AF%22%5D%0A%20%20VN%20--%3E%20CN%5B%22%E6%A0%A1%E9%AA%8C%E8%8A%82%E7%82%B9%3A%20%E6%8C%89%E6%9C%AC%E7%BB%84%E5%A5%87%E5%81%B6%E7%BA%A6%E6%9D%9F%E5%9B%9E%E4%BC%A0%E4%BF%AE%E6%AD%A3%E4%BC%BC%E7%84%B6%22%5D%0A%20%20CN%20--%3E%20VN2%5B%22%E5%8F%98%E9%87%8F%E8%8A%82%E7%82%B9%E5%86%8D%E6%B1%87%E6%80%BB%2C%20%E6%9B%B4%E6%96%B0%E5%90%84%E6%AF%94%E7%89%B9%E5%88%A4%E5%86%B3%22%5D%0A%20%20VN2%20--%3E%20CHK%7B%22%E5%85%A8%E9%83%A8%E6%A0%A1%E9%AA%8C%E6%96%B9%E7%A8%8B%E6%BB%A1%E8%B6%B3%3F%22%7D%0A%20%20CHK%20--%3E%7C%22%E6%98%AF%22%7C%20OK%5B%22%E8%BE%93%E5%87%BA%E8%AF%91%E7%A0%81%E7%BB%93%E6%9E%9C%22%5D%0A%20%20CHK%20--%3E%7C%22%E5%90%A6%E4%B8%94%E6%9C%AA%E8%B6%85%E8%BD%AE%E6%95%B0%22%7C%20VN%0A%20%20CHK%20--%3E%7C%22%E8%B6%85%E8%BD%AE%E6%95%B0%22%7C%20FAIL%5B%22%E5%AE%A3%E5%91%8A%E8%AF%91%E7%A0%81%E5%A4%B1%E8%B4%A5%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p>这张图回答的问题：一次「迭代消息传递」内部消息怎么流、何时停。变量节点收信、校验节点质证、再汇总，循环到全部校验满足或轮数用尽——这与上图「设计层面的构造链」互补，是运行层面的译码循环。</p><p>与单向函数无关：这里的「随机」是码设计，不是密码学困难。</p><p>密度演化在树状展开上追踪消息分布，预测门限。有环则分析是近似。极化码（Arikan）用另一条可证达容量的构造，5G 控制信道用过，本课点名。平层：增大最小距离或外接 RS 可压。短码场景代数码仍常胜。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不推密度演化积分，不写 5G NR 的基图。不引入极化码（Arikan）全文，点名：另一条达容量路线。后课默认：近容量实用码 = 稀疏图迭代。下一课允许失真：率失真。</p><p>近容量来自长码上的统计门限，不是精确 \\(d_{\\min}\\) 设计。BP 有环时非 ML。与 PCP 的「局部校验」同形不同题：这里是信道噪声，那里是证明系统。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LDPC：稀疏校验 + 迭代 BP；Turbo：交织卷积互译。</li><li>逼近 \\(C\\)，代价是长码、平层、非 ML。</li><li>与代数码分工：统计门限 vs \\(d_{\\min}\\)。</li><li>出处：Gallager, 1963；Berrou et al., 1993；Richardson and Urbanke。</li></ul>',8))])}const T=i(p,[["render",C]]);export{c as __pageData,T as default};
